  op('css-beautify', 'CSS beautify', 'Code', 'One declaration per line, indented.', [{ key: 'indent', label: 'Indent', type: 'select', options: ['2', '4', 'tab'], def: '2' }], function (s, a) { var ind = a.indent === 'tab' ? '\t' : ' '.repeat(+a.indent), depth = 0, out = '', buf = '', q = null; for (var i = 0; i < s.length; i++) { var c = s[i]; if (q) { buf += c; if (c === q && s[i - 1] !== '\\') q = null; continue; } if (c === '"' || c === "'") { q = c; buf += c; continue; } if (c === '/' && s[i + 1] === '*') { var e = s.indexOf('*/', i + 2); e = e < 0 ? s.length : e + 2; out += ind.repeat(depth) + s.slice(i, e) + '\n'; i = e - 1; continue; } if (c === '{') { out += ind.repeat(depth) + buf.trim().replace(/\s+/g, ' ').replace(/\s*,\s*/g, ', ') + ' {\n'; buf = ''; depth++; } else if (c === ';') { if (buf.trim()) out += ind.repeat(depth) + buf.trim().replace(/\s*:\s*/, ': ') + ';\n'; buf = ''; } else if (c === '}') { if (buf.trim()) out += ind.repeat(depth) + buf.trim().replace(/\s*:\s*/, ': ') + ';\n'; buf = ''; depth = Math.max(0, depth - 1); out += ind.repeat(depth) + '}\n'; } else buf += c; } return (out + buf.trim()).trim(); });
